function initMemberDome(){
  const root=document.querySelector('[data-member-dome]');
  const sphere=root?.querySelector('[data-dome-sphere]');
  if(!root||!sphere)return;
  const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
  let rotation={x:-4,y:0},start={x:0,y:0,rx:0,ry:0},velocity={x:0,y:0};
  let dragging=false,moved=false,paused=false,last=performance.now(),lastPoint=null,inertia=0,activeLink=null;
  const clamp=(value,min,max)=>Math.min(max,Math.max(min,value));
  const apply=()=>{sphere.style.transform=`translateZ(calc(var(--dome-radius) * -1)) rotateX(${rotation.x}deg) rotateY(${rotation.y}deg)`};
  const stopInertia=()=>{if(inertia)cancelAnimationFrame(inertia);inertia=0};
  const glide=()=>{velocity.x*=.94;velocity.y*=.94;rotation.y+=velocity.x;rotation.x=clamp(rotation.x-velocity.y,-20,20);apply();if(Math.abs(velocity.x)+Math.abs(velocity.y)>.015)inertia=requestAnimationFrame(glide);else inertia=0};
  const tick=now=>{if(!reduced&&!dragging&&!paused&&!inertia)rotation.y+=(now-last)*.0035;last=now;apply();requestAnimationFrame(tick)};
  requestAnimationFrame(tick);

  const viewer=document.createElement('div');
  viewer.className='dome-viewer';
  viewer.hidden=true;
  viewer.innerHTML='<button class="dome-viewer-scrim" type="button" aria-label="Chiudi anteprima Member"></button><article class="dome-viewer-card" role="dialog" aria-modal="true" aria-labelledby="dome-viewer-name"><button class="dome-viewer-close" type="button" aria-label="Chiudi anteprima"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"/></svg></button><span><img data-dome-viewer-image src="assets/logos/imland-member.svg" alt="IMLAND Member"></span><h3 id="dome-viewer-name" data-dome-viewer-name></h3><a data-dome-viewer-link>Vai alla scheda Member <b aria-hidden="true">↗</b></a></article>';
  root.append(viewer);
  const closeButton=viewer.querySelector('.dome-viewer-close');
  const closeViewer=()=>{if(viewer.hidden)return;viewer.classList.remove('is-open');setTimeout(()=>{viewer.hidden=true;activeLink?.focus();activeLink=null;paused=false},reduced?0:260)};
  const openViewer=link=>{activeLink=link;paused=true;const image=link.querySelector('img');viewer.querySelector('[data-dome-viewer-image]').src=image.currentSrc||image.src;viewer.querySelector('[data-dome-viewer-image]').alt=image.alt;viewer.querySelector('[data-dome-viewer-name]').textContent=image.alt;viewer.querySelector('[data-dome-viewer-link]').href=link.getAttribute('href');viewer.hidden=false;requestAnimationFrame(()=>viewer.classList.add('is-open'));closeButton.focus()};
  viewer.querySelector('.dome-viewer-scrim').addEventListener('click',closeViewer);
  closeButton.addEventListener('click',closeViewer);
  viewer.querySelector('[data-dome-viewer-link]').addEventListener('click',event=>{const target=document.querySelector(event.currentTarget.getAttribute('href'));if(!target)return;event.preventDefault();viewer.hidden=true;viewer.classList.remove('is-open');target.scrollIntoView({behavior:reduced?'auto':'smooth',block:'center'});target.focus({preventScroll:true})});
  root.addEventListener('keydown',event=>{if(event.key==='Escape')closeViewer()});

  root.addEventListener('pointerdown',event=>{if(event.target.closest('.dome-viewer'))return;stopInertia();dragging=true;moved=false;velocity={x:0,y:0};start={x:event.clientX,y:event.clientY,rx:rotation.x,ry:rotation.y};lastPoint={x:event.clientX,y:event.clientY,time:performance.now()};root.classList.add('is-dragging')});
  root.addEventListener('pointermove',event=>{if(!dragging)return;const dx=event.clientX-start.x,dy=event.clientY-start.y;if(!moved&&Math.hypot(dx,dy)>5){moved=true;root.setPointerCapture?.(event.pointerId)}rotation.y=start.ry+dx/10;rotation.x=clamp(start.rx-dy/14,-20,20);const now=performance.now(),elapsed=Math.max(16,now-lastPoint.time);velocity={x:(event.clientX-lastPoint.x)/elapsed*.65,y:(event.clientY-lastPoint.y)/elapsed*.65};lastPoint={x:event.clientX,y:event.clientY,time:now};apply()});
  const finish=()=>{if(!dragging)return;dragging=false;root.classList.remove('is-dragging');if(!reduced&&moved&&(Math.abs(velocity.x)+Math.abs(velocity.y)>.02))inertia=requestAnimationFrame(glide)};
  root.addEventListener('pointerup',finish);
  root.addEventListener('pointercancel',finish);
  root.addEventListener('mouseenter',()=>{paused=true});
  root.addEventListener('mouseleave',()=>{if(viewer.hidden)paused=false;finish()});
  root.addEventListener('focusin',()=>{paused=true});
  root.addEventListener('focusout',event=>{if(viewer.hidden&&!root.contains(event.relatedTarget))paused=false});
  root.addEventListener('click',event=>{if(moved||event.target.closest('.dome-viewer'))return;const links=[...root.querySelectorAll('[data-member-logo]')],link=links.map(node=>{const rect=node.getBoundingClientRect();return {node,rect,distance:Math.hypot(event.clientX-(rect.left+rect.width/2),event.clientY-(rect.top+rect.height/2))}}).filter(({rect})=>event.clientX>=rect.left&&event.clientX<=rect.right&&event.clientY>=rect.top&&event.clientY<=rect.bottom).sort((a,b)=>a.distance-b.distance)[0]?.node;if(!link)return;event.preventDefault();location.hash=link.getAttribute('href')});
}
