function setMenuState(open,{restoreFocus=false}={}){
  if(!header||!menu||!siteMenu)return;
  const backgroundTargets=document.querySelectorAll('main,footer,.player,.floating-actions,.brand,.mini-cta,.account-link,.search-toggle');
  header.classList.toggle('open',open);
  document.body.classList.toggle('menu-open',open);
  backgroundTargets.forEach(target=>{target.inert=open});
  menu.setAttribute('aria-expanded',String(open));
  menu.setAttribute('aria-label',open?'Chiudi menu':'Apri menu');
  siteMenu.setAttribute('aria-hidden',String(!open));
  if(open){header.classList.remove('search-open');searchToggle?.setAttribute('aria-expanded','false');setTimeout(()=>siteMenu.querySelector('a')?.focus(),420)}
  else if(restoreFocus)menu.focus();
}
function closeHeaderPanels({restoreFocus=false}={}){setMenuState(false,{restoreFocus});header?.classList.remove('search-open');searchToggle?.setAttribute('aria-expanded','false')}
menu?.addEventListener('click',()=>setMenuState(!header.classList.contains('open')));
