function applyNowPlaying(data){if(!data?.ok||audio?.dataset.mode==='podcast')return;const title=String(data.trackTitle||data.stationName||'IMLAND Radio').trim();const artist=String(data.trackArtist||data.stationName||'Diretta ufficiale').trim();const cover=verifiedCover(data.trackImage||data.stationImage);document.querySelectorAll('[data-radio-title]').forEach(item=>item.textContent=title);document.querySelectorAll('[data-radio-artist]').forEach(item=>item.textContent=artist);document.querySelectorAll('[data-radio-detail]').forEach(item=>item.textContent=`${artist} · ${data.stationName||'IMLAND Radio'}`);document.querySelectorAll('[data-radio-cover]').forEach(image=>{image.src=cover;image.alt=`In onda: ${title}`});player.dataset.metadata='live';if('mediaSession'in navigator&&'MediaMetadata'in window)navigator.mediaSession.metadata=new MediaMetadata({title,artist,album:data.stationName||'IMLAND Radio',artwork:[{src:cover}]})}
async function refreshNowPlaying(){if(!player)return;let delay=30000;try{const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),7000);const response=await fetch(nowPlayingEndpoint,{cache:'no-store',signal:controller.signal});clearTimeout(timeout);if(!response.ok)throw new Error(`Now playing ${response.status}`);const data=await response.json();if(!data?.ok)throw new Error('Now playing unavailable');applyNowPlaying(data);delay=Math.max(15000,Math.min(60000,(Number(data.ttl)||20)*1000))}catch{player.dataset.metadata='unavailable';if(!document.querySelector('[data-radio-title]')?.textContent.trim())document.querySelectorAll('[data-radio-title]').forEach(item=>item.textContent='IMLAND Radio');document.querySelectorAll('[data-radio-cover]').forEach(image=>{if(!image.getAttribute('src'))image.src=radioFallbackCover})}finally{clearTimeout(nowPlayingTimer);nowPlayingTimer=setTimeout(refreshNowPlaying,delay)}}
