async function ensureRadioPlayback(){if(!audio||radioPlayback.intent!=='playing')return false;if(audio.dataset.mode!=='radio'||!audio.src.includes('ylpompusqpatv')){audio.dataset.mode='radio';player.dataset.mode='radio';playerRewinds.forEach(control=>control.disabled=true);audio.src=radioStreamUrl;audio.load()}audio.volume=Math.max(0,Math.min(1,Number(radioPlayback.volume)||.8));audio.muted=Boolean(radioPlayback.muted);try{await audio.play();return true}catch{player.dataset.resumePending='true';setStreamStatus('idle','PREMI PLAY');return false}}
const recoverRadio=()=>{clearTimeout(radioRecoveryTimer);if(radioPlayback.intent!=='playing'||audio?.dataset.mode==='podcast')return;radioRecoveryTimer=setTimeout(()=>ensureRadioPlayback(),350)};
