async function toggleRadio(){if(!audio)return;if(audio.dataset.mode==='radio'&&!audio.paused){setRadioIntent('paused');audio.pause();return}setRadioIntent('playing');setStreamStatus('loading','CARICAMENTO');if(!await ensureRadioPlayback()){setPlayerOpen(true);if(playerCopy?.querySelector('span'))playerCopy.querySelector('span').textContent='Premi Play per riattivare la diretta'} }
